// Your first program: console.log() writes a line in the console.
console.log("Hello, world!");
console.log("I am learning JavaScript with DMarlon Studio.");

// console.log() accepts several values and separates them with a space.
console.log("2 + 3 =", 2 + 3);
console.log("Three coffees at 1.5 euros:", 3 * 1.5, "euros");

/* A comment can also span
   several lines, like this one. */
console.log("Bye!");

// const: a value that will not change. let: a value that can change.
const shopName = "Corner Bakery";
let loavesLeft = 40;
console.log(shopName, "opens with", loavesLeft, "loaves");

loavesLeft = loavesLeft - 12; // let accepts a new value
console.log("After the morning rush:", loavesLeft);

// typeof tells you the type of any value.
const price = 1.25;
const isOpen = true;
let nextDelivery; // declared, but without a value yet
const closedDay = null;

console.log(typeof shopName);  // string
console.log(typeof price);     // number
console.log(typeof isOpen);    // boolean
console.log(typeof nextDelivery, nextDelivery);
console.log(typeof closedDay); // "object": an old quirk of the language

// The type belongs to the value, not to the variable.
let label = 42;
console.log(typeof label);
label = "forty-two";
console.log(typeof label);

// Giving a const a new value is an error (remove the // to see it):
// shopName = "New Bakery";

// Whole numbers and decimals are all of type "number".
const width = 4.5; // metres
const length = 3.2;
const area = width * length;
console.log("Area:", area, "m2");
console.log("Rounded:", Math.round(area), "| Two decimals:", area.toFixed(2));

// Division, whole part and remainder
const eggs = 27;
console.log("27 / 12 =", eggs / 12);
console.log("Full boxes of 12:", Math.floor(eggs / 12));
console.log("Eggs left over:", eggs % 12);

// Powers and roots
console.log("2 to the 10th:", 2 ** 10, "| Square root of 144:", Math.sqrt(144));

// Highest, lowest, rounding up
console.log("Warmest day:", Math.max(14, 19, 23, 17, 9));
console.log("Coldest day:", Math.min(14, 19, 23, 17, 9));
console.log("Buses for 130 people (55 seats):", Math.ceil(130 / 55));

// Decimals are not always exact in binary:
console.log(0.1 + 0.2, "->", (0.1 + 0.2).toFixed(2));

// From text to number
console.log(Number("42") + 8, "| parseInt:", parseInt("15 kg"), "| Not a number:", Number("abc"));

const product = "Running shoes";
const price = 59.9;
const quantity = 2;

// Joining strings with +
console.log("Product: " + product);

// Template literals: backticks and ${...} for any expression
console.log(`${quantity} x ${product} = ${price * quantity} euros`);

// Length and single characters (positions start at 0)
console.log(`"${product}" has ${product.length} characters`);
console.log("First letter:", product[0], "| Last:", product[product.length - 1]);

// Upper and lower case
console.log(product.toUpperCase());
console.log(product.toLowerCase());

// Searching inside a string
console.log("Contains 'shoes'?", product.includes("shoes"));
console.log("Starts with 'Run'?", product.startsWith("Run"));

// Template literals can span several lines
const receipt = `--- Receipt ---
Item:  ${product}
Total: ${(price * quantity).toFixed(2)} euros`;
console.log(receipt);

// if runs a block only when its condition is true.
const grade = 7.5;
if (grade >= 5) {
  console.log(`Grade ${grade}: passed`);
} else {
  console.log(`Grade ${grade}: failed`);
}

// else if checks conditions in order; the first true one wins.
const temperature = 12;
if (temperature >= 30) {
  console.log("Hot: drink plenty of water");
} else if (temperature >= 18) {
  console.log("Mild: perfect for a walk");
} else if (temperature >= 5) {
  console.log("Cool: take a jacket");
} else {
  console.log("Cold: better stay indoors");
}

// The ternary operator: condition ? valueIfTrue : valueIfFalse
const basketTotal = 42;
const shipping = basketTotal >= 50 ? 0 : 4.95;
console.log(`Basket: ${basketTotal} euros | Shipping: ${shipping} euros`);

const items = 1;
console.log(`${items} ${items === 1 ? "item" : "items"} in the basket`);

const lives = 0;
console.log(lives > 0 ? "Keep playing" : "Game over");

// === compares value AND type; == converts types first (avoid it).
console.log('5 === 5:    ', 5 === 5);
console.log('5 === "5":  ', 5 === "5");
console.log('5 == "5":   ', 5 == "5");
console.log("0 == false: ", 0 == false, "| 0 === false:", 0 === false);
console.log('"apple" !== "Apple":', "apple" !== "Apple");

// Logical operators: && (and), || (or), ! (not)
const age = 16;
const withAdult = true;
console.log("Can enter the concert:", age >= 18 || withAdult);

const isMember = true;
const total = 80;
console.log("Gets the discount:", isMember && total >= 50);
console.log("Is not a member:", !isMember);

// Truthy and falsy: in an if, every value counts as true or false.
// Falsy: false, 0, "", null, undefined and NaN. Everything else is truthy.
const username = "";
if (username) {
  console.log(`Welcome, ${username}`);
} else {
  console.log("Please type your name");
}

// || gives the first truthy value: handy for defaults.
console.log("Name shown:", username || "Guest");
console.log("Boolean(0):", Boolean(0), "| Boolean('0'):", Boolean("0"));

// for: start; condition; step. A multiplication table.
for (let i = 1; i <= 5; i++) {
  console.log(`7 x ${i} = ${7 * i}`);
}

// while repeats as long as the condition is true.
// 100 euros saved, +5% every year: how long until 130?
let savings = 100;
let years = 0;
while (savings < 130) {
  savings = savings * 1.05;
  years++;
}
console.log(`After ${years} years: ${savings.toFixed(2)} euros`);

// continue jumps to the next round; break leaves the loop.
for (let level = 1; level <= 10; level++) {
  if (level % 2 === 0) continue; // skip even levels
  if (level > 7) break;          // stop after level 7
  console.log("Playing level", level);
}

// A loop that builds a string step by step
let countdown = "";
for (let n = 5; n >= 1; n--) {
  countdown += n + " ";
}
console.log(countdown + "Lift-off!");

// An array is an ordered list inside [ ].
const fruits = ["apple", "banana", "cherry", "mango"];
console.log(fruits);
console.log("How many:", fruits.length);

// Positions (indexes) start at 0.
console.log("First:", fruits[0], "| Last:", fruits[fruits.length - 1]);
console.log("Position 10:", fruits[10]);

// Change an element through its index.
fruits[1] = "kiwi";
console.log("After the change:", fruits);

// An array of numbers: one week of temperatures.
const temps = [18, 21, 19, 24, 26, 22, 17];
let sum = 0;
for (let i = 0; i < temps.length; i++) {
  sum += temps[i];
}
console.log("Average temperature:", (sum / temps.length).toFixed(1));

// for...of goes through the values directly, without indexes.
let warmDays = 0;
for (const t of temps) {
  if (t >= 22) warmDays++;
}
console.log("Days at 22 or more:", warmDays);

// An array of arrays: a noughts and crosses board.
const board = [["X", "O", "X"], [" ", "X", "O"], ["O", " ", "X"]];
console.log("Centre square:", board[1][1]);
for (const row of board) console.log(row);

// A shopping list that changes as we go.
const list = ["bread", "milk", "eggs"];

list.push("cheese");        // add at the end
console.log("push:   ", list);
const last = list.pop();    // remove from the end
console.log("pop:    ", list, "removed", last);

list.unshift("coffee");     // add at the start
console.log("unshift:", list);
const first = list.shift(); // remove from the start
console.log("shift:  ", list, "removed", first);

// includes and indexOf: is it there, and where?
console.log("Has milk?", list.includes("milk"));
console.log("Position of eggs:", list.indexOf("eggs"));
console.log("Position of tea:", list.indexOf("tea")); // -1: not found

// slice copies a part and leaves the original as it was.
const queue = ["Ana", "Ben", "Carla", "David", "Eva"];
console.log("First three:", queue.slice(0, 3));
console.log("From the third on:", queue.slice(2));

// splice changes the original: it removes and/or inserts.
const removed = queue.splice(1, 2); // remove 2 from index 1
console.log("splice removed", removed, "->", queue);
queue.splice(1, 0, "Fran");         // insert at index 1, remove none
console.log("After inserting:", queue);

// An object groups related data as key: value pairs.
const book = {
  title: "Dune",
  author: "F. Herbert",
  year: 1965,
  available: true,
};
console.log(book);

// Read a property with a dot, or with brackets and a string.
const field = "year";
console.log("Title:", book.title, "| Year:", book[field]);

// Change, add and delete properties.
book.available = false;
book.pages = 412;
delete book.year;
console.log(book);
console.log("Has pages?", "pages" in book, "| Keys:", Object.keys(book));

// for...in goes through the keys of an object.
for (const key in book) {
  console.log(`  ${key}: ${book[key]}`);
}

// An array of objects: the usual way to keep records.
const students = [
  { name: "Lucia", grade: 8.5 },
  { name: "Mario", grade: 6 },
];
for (const s of students) console.log(`${s.name} got ${s.grade}`);

// A function declaration: a named block of code you can reuse.
function greet(name) {
  console.log(`Hello, ${name}! Welcome to the shop.`);
}
greet("Laura");
greet("Pedro");

// A function can calculate a value and return it.
function celsiusToFahrenheit(celsius) {
  return celsius * 9 / 5 + 32;
}
console.log("20 C =", celsiusToFahrenheit(20), "F");
console.log("-5 C =", celsiusToFahrenheit(-5), "F");

// Arrow functions: a shorter way to write a function.
const double = (n) => n * 2;
const isEven = (n) => n % 2 === 0;
console.log("double(21):", double(21), "| isEven(7):", isEven(7));

// With several lines, an arrow function needs { } and return.
const shippingCost = (total) => {
  if (total >= 50) return 0;
  return 4.95;
};
console.log("Shipping for 30 euros:", shippingCost(30));
console.log("Shipping for 75 euros:", shippingCost(75));

// Functions are values: you can pass them to other functions.
const applyTwice = (fn, value) => fn(fn(value));
console.log("applyTwice(double, 5):", applyTwice(double, 5));

// Declarations can be called before they appear in the file.
console.log("square(9):", square(9));
function square(n) { return n * n; }

// Default values are used when an argument is missing.
function orderCoffee(size = "medium", sugar = 1) {
  return `${size} coffee with ${sugar} sugar`;
}
console.log(orderCoffee("large", 2));
console.log(orderCoffee("small"));
console.log(orderCoffee());

// return ends the function at once: useful to stop early.
function finalPrice(price, discountPercent = 0) {
  if (price < 0) return "invalid price";
  const discount = price * discountPercent / 100;
  return price - discount;
}
console.log(finalPrice(80, 25), "|", finalPrice(80), "|", finalPrice(-5, 10));

// Without return, a function gives back undefined.
function showScore(points) {
  console.log("Score:", points);
}
console.log("showScore returned:", showScore(120));

// Rest parameters (...) collect any number of arguments in an array.
function average(...grades) {
  let sum = 0;
  for (const g of grades) sum += g;
  return grades.length > 0 ? sum / grades.length : 0;
}
console.log("Average:", average(6, 7.5, 9), "| Of nothing:", average());

// To give back several values, return an object.
const stats = (a, b) => ({ total: a + b, difference: a - b });
console.log(stats(30, 12));

const products = [
  { name: "Keyboard", price: 45, stock: 12 },
  { name: "Mouse", price: 20, stock: 0 },
  { name: "Monitor", price: 180, stock: 4 },
  { name: "Webcam", price: 60, stock: 0 },
  { name: "Headset", price: 75, stock: 7 },
];

// forEach runs a function for every element (and returns nothing).
products.forEach((p, i) => {
  console.log(`${i + 1}. ${p.name} - ${p.price} euros`);
});

// map builds a NEW array with one result per element.
const names = products.map((p) => p.name);
console.log("Names:", names);
const withVat = products.map((p) => (p.price * 1.21).toFixed(2));
console.log("With VAT:", withVat);

// filter keeps only the elements for which the function returns true.
const inStock = products.filter((p) => p.stock > 0);
console.log("In stock:", inStock.map((p) => p.name));
const cheap = products.filter((p) => p.price < 50);
console.log("Under 50 euros:", cheap.length, "products");

// Chaining: filter first, then map. The original stays the same.
const sale = products
  .filter((p) => p.stock > 0 && p.price > 50)
  .map((p) => `${p.name} at ${p.price * 0.9}`);
console.log("On sale (-10%):", sale);
console.log("The original still has", products.length, "products");

const orders = [
  { id: 101, customer: "Ana", total: 35.5, paid: true },
  { id: 102, customer: "Luis", total: 120, paid: true },
  { id: 103, customer: "Marta", total: 64.25, paid: false },
  { id: 104, customer: "Ana", total: 18, paid: true },
];

// reduce combines all the elements into one value: here, a sum.
const revenue = orders.reduce((sum, o) => sum + o.total, 0);
console.log("Total of all orders:", revenue);

// The starting value can be anything, such as an object to group.
const perCustomer = orders.reduce((acc, o) => {
  acc[o.customer] = (acc[o.customer] || 0) + o.total;
  return acc;
}, {});
console.log("Per customer:", perCustomer);

// Without a starting value, reduce begins with the first element.
const biggest = orders.reduce((best, o) => (o.total > best.total ? o : best));
console.log("Biggest order:", biggest.id, "by", biggest.customer);

// find returns the FIRST element that matches (or undefined).
const unpaid = orders.find((o) => !o.paid);
console.log("First unpaid:", unpaid.id, unpaid.customer);
console.log("Order 999:", orders.find((o) => o.id === 999));
console.log("Position of 103:", orders.findIndex((o) => o.id === 103));

// some: is there at least one? every: are all of them?
console.log("Any order over 100?", orders.some((o) => o.total > 100));
console.log("All paid?", orders.every((o) => o.paid));

// Text typed by people is often messy.
const raw = "   Margarita, Pepperoni , Four Cheese,Hawaiian  ";

// trim removes the spaces at both ends.
const clean = raw.trim();
console.log(`[${clean}]`);

// split cuts a string into an array; join glues an array back.
const pizzas = clean.split(",").map((p) => p.trim());
console.log(pizzas);
console.log(pizzas.join(" | "));

// replace changes the first match; replaceAll changes all of them.
const notice = "Today: Margarita. Margarita for 8 euros.";
console.log(notice.replace("Margarita", "Hawaiian"));
console.log(notice.replaceAll("Margarita", "Pepperoni"));

// padEnd and padStart fill up to a length: perfect for columns.
const menu = [["Margarita", 8], ["Pepperoni", 9.5], ["Four Cheese", 11]];
for (const item of menu) {
  console.log(item[0].padEnd(14, ".") + item[1].toFixed(2).padStart(7));
}
console.log("Order number", String(42).padStart(5, "0"));

// slice, indexOf and repeat
const code = "ORD-00042-PIZZA";
const dash = code.indexOf("-");
console.log("Prefix:", code.slice(0, dash), "| Type:", code.slice(code.lastIndexOf("-") + 1));
console.log("=".repeat(21));

// Array destructuring: take the values out by position.
const podium = ["Lewis", "Max", "Charles", "Lando", "Oscar"];
const [gold, silver, bronze, ...rest] = podium;
console.log(`Gold: ${gold}, silver: ${silver}, bronze: ${bronze}`);
console.log("The rest:", rest);

// Swap two variables without a temporary one.
let home = 2;
let away = 3;
[home, away] = [away, home];
console.log("Swapped score:", home, "-", away);

// Object destructuring: take the values out by name.
const player = { name: "Nora", level: 12, coins: 340 };
const { name, level, lives = 3 } = player; // lives gets a default
console.log(`${name} is on level ${level} with ${lives} lives`);

// Destructuring in parameters and in for...of
const describe = ({ name, coins }) => `${name} has ${coins} coins`;
console.log(describe(player));
for (const [item, qty] of Object.entries({ swords: 2, potions: 5 })) {
  console.log(`  ${item}: ${qty}`);
}

// Spread (...) unpacks arrays and objects to copy or combine them.
const weekA = [12, 15];
const weekB = [9, 20];
const scores = [...weekA, ...weekB, 30];
console.log("All scores:", scores, "| Best:", Math.max(...scores));

const upgraded = { ...player, level: 13, coins: player.coins + 50 };
console.log("Before:", player);
console.log("After: ", upgraded);

// An object in memory: a saved game.
const save = {
  player: "Nora",
  level: 7,
  inventory: ["sword", "potion"],
  settings: { music: true, volume: 8 },
};

// JSON.stringify turns it into text, ready to store or send.
const text = JSON.stringify(save);
console.log(text);
console.log("Type:", typeof text, "| Length:", text.length);

// With a third argument, the text is indented and easier to read.
console.log(JSON.stringify(save.settings, null, 2));

// JSON.parse turns the text back into an object: a separate copy.
const loaded = JSON.parse(text);
loaded.level += 1;
console.log(`${loaded.player} goes on to level ${loaded.level}`);
console.log("Second item:", loaded.inventory[1], "| Saved level:", save.level);

// Data from a server arrives as JSON text.
const reply = '{"city":"Madrid","temps":[21,24,19],"rain":null}';
const weather = JSON.parse(reply);
console.log(weather.city, "| Max:", Math.max(...weather.temps), "| Rain:", weather.rain);

// JSON has no undefined or functions: those keys are left out.
const item = { name: "pen", note: undefined, price: 1.5, show: () => 1 };
console.log(JSON.stringify(item));

